"use client"

import { forwardRef, useId, useImperativeHandle, type ReactNode } from "react"

import {
  useCurrencyInput,
  type UseCurrencyInputOptions,
} from "./use-currency-input"

export type CurrencyLayout = "inline" | "display" | "stepper"

export interface CurrencyInputProps extends UseCurrencyInputOptions {
  /** Visible label. Supply this or `aria-label` — a field with neither has no accessible name. */
  label?: ReactNode
  /** Helper text under the field. Replaced by the error message while one is showing. */
  hint?: ReactNode
  /** PRD §6 layouts. `inline` is the default form-row shape. */
  layout?: CurrencyLayout
  /** Show the ISO code as a trailing affix. Default true. */
  showCode?: boolean
}

const MINUS = (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" aria-hidden="true">
    <path d="M5 12h14" />
  </svg>
)
const PLUS = (
  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" aria-hidden="true">
    <path d="M12 5v14M5 12h14" />
  </svg>
)

/**
 * A money field.
 *
 * Emits an INTEGER count of minor units — 123450 is $1,234.50 — so no float
 * ever touches a price. Typing fills from the right like a register, which is
 * also why the caret cannot drift: there is no string being edited.
 */
export const CurrencyInput = forwardRef<HTMLInputElement, CurrencyInputProps>(
  function CurrencyInput(
    { label, hint, layout = "inline", showCode = true, className, id: idProp, ...rest },
    ref,
  ) {
    const reactId = useId()
    const id = idProp ?? reactId

    const api = useCurrencyInput({ ...rest, id })
    const {
      inputProps,
      ariaProps,
      containerProps,
      hiddenInputProps,
      ownsErrorUI,
      errorText,
      errorId,
      visible,
      symbol,
      currency,
      step,
      sideEffect,
      undoPaste,
      dismissSideEffect,
    } = api

    useImperativeHandle(
      ref,
      () =>
        inputProps.ref.current ??
        ({ focus: () => inputProps.ref.current?.focus() } as HTMLInputElement),
      [inputProps.ref],
    )

    const field = (
      <input
        {...inputProps}
        {...ariaProps}
        id={id}
        className={layout === "display" ? "inputcn-display-input" : "inputcn-bare"}
        aria-label={rest["aria-label"]}
        aria-labelledby={rest["aria-labelledby"]}
      />
    )

    const invalid = ariaProps["aria-invalid"] ? "true" : undefined

    return (
      <div
        className={`inputcn-field inputcn-currency-${layout} ${className ?? ""}`.trim()}
        {...containerProps}
      >
        {label === undefined ? null : (
          <label className="inputcn-label" htmlFor={id}>
            {label}
          </label>
        )}

        {layout === "display" ? (
          <div className="inputcn-display" data-invalid={invalid}>
            <span className="inputcn-display-symbol" aria-hidden="true">
              {symbol}
            </span>
            {field}
            {showCode ? (
              <span className="inputcn-display-code" aria-hidden="true">
                {currency}
              </span>
            ) : null}
          </div>
        ) : layout === "stepper" ? (
          <div className="inputcn-stepper">
            <button
              type="button"
              className="inputcn-stepbtn"
              onClick={() => step(-1)}
              disabled={rest.disabled}
              aria-label="Decrease"
              tabIndex={-1}
            >
              {MINUS}
            </button>
            <div className="inputcn-group" data-invalid={invalid}>
              <span className="inputcn-affix" aria-hidden="true">
                {symbol}
              </span>
              {field}
            </div>
            <button
              type="button"
              className="inputcn-stepbtn"
              onClick={() => step(1)}
              disabled={rest.disabled}
              aria-label="Increase"
              tabIndex={-1}
            >
              {PLUS}
            </button>
          </div>
        ) : (
          <div className="inputcn-group" data-invalid={invalid}>
            <span className="inputcn-affix" aria-hidden="true">
              {symbol}
            </span>
            {field}
            {showCode ? (
              <span className="inputcn-affix inputcn-affix-right" aria-hidden="true">
                {currency}
              </span>
            ) : null}
          </div>
        )}

        {sideEffect ? (
          <p className="inputcn-notice" role="status">
            {sideEffect.label}
            <button type="button" onClick={undoPaste} className="inputcn-undo">
              Undo
            </button>
            <button
              type="button"
              onClick={dismissSideEffect}
              className="inputcn-dismiss"
              aria-label="Dismiss"
            >
              ×
            </button>
          </p>
        ) : null}

        {ownsErrorUI && errorText ? (
          <p
            id={errorId}
            className={visible?.warning ? "inputcn-warning" : "inputcn-error"}
            // Stable rule name so a test can assert WHICH rule failed rather
            // than matching copy, which breaks on a rewrite or a locale change.
            data-rule={visible?.rule}
            role="alert"
          >
            {errorText}
          </p>
        ) : hint !== undefined ? (
          <p className="inputcn-hint">{hint}</p>
        ) : null}

        {hiddenInputProps ? <input {...hiddenInputProps} /> : null}
      </div>
    )
  },
)

"use client"

import {
  useCallback,
  useMemo,
  useRef,
  useState,
  type ClipboardEvent,
  type KeyboardEvent,
} from "react"

import { clipboardText } from "@inputcn/core/paste"
import type { BaseFieldProps, Rule } from "@inputcn/core/types"
import { useField, type UseFieldResult } from "@inputcn/core/use-field"
import {
  custom,
  integer as integerRule,
  max as maxRule,
  min as minRule,
  multipleOf as multipleOfRule,
  negative as negativeRule,
  nonZero as nonZeroRule,
  positive as positiveRule,
  required as requiredRule,
  rules,
} from "@inputcn/core/validity"

import {
  currencySymbol,
  formatMinor,
  fractionDigits,
  negate,
  parsePastedMoney,
  popDigit,
  pushDigit,
} from "./currency"

export interface CurrencyConstraints {
  /** Minor units. */
  min?: number
  /** Minor units. */
  max?: number
  positive?: boolean
  negative?: boolean
  nonZero?: boolean
  /** Reject fractional currency units (e.g. whole dollars only). */
  wholeUnitsOnly?: boolean
  /** Minor units the value must be a multiple of. */
  multipleOf?: number
}

export interface UseCurrencyInputOptions
  extends BaseFieldProps<number>,
    CurrencyConstraints {
  /** ISO 4217. Default "USD". */
  currency?: string
  /** BCP 47. Default "en-US". */
  locale?: string
  /** Allow typing a negative value with "-". Default false. */
  allowNegative?: boolean
  /** Stepper increment in minor units. Default one whole unit. */
  step?: number
}

export interface UseCurrencyInputResult extends UseFieldResult<number> {
  currency: string
  locale: string
  symbol: string
  /** The formatted string currently shown. */
  display: string
  fractionDigits: number
  step: (direction: 1 | -1) => void
  inputProps: {
    ref: React.RefObject<HTMLInputElement | null>
    value: string
    onChange: () => void
    onKeyDown: (e: KeyboardEvent<HTMLInputElement>) => void
    onPaste: (e: ClipboardEvent<HTMLInputElement>) => void
    inputMode: "decimal"
    autoComplete: "off"
    disabled: boolean | undefined
    readOnly: boolean | undefined
    placeholder: string | undefined
  }
  sideEffect: { from: string; to: string; label: string } | null
  dismissSideEffect: () => void
  undoPaste: () => void
}

const ALLOWED_KEYS = new Set([
  "Tab",
  "Enter",
  "Escape",
  "ArrowLeft",
  "ArrowRight",
  "Home",
  "End",
])

export function useCurrencyInput(
  options: UseCurrencyInputOptions,
): UseCurrencyInputResult {
  const {
    currency = "USD",
    locale = "en-US",
    allowNegative = false,
    step: stepProp,
    min,
    max,
    positive,
    negative,
    nonZero,
    wholeUnitsOnly,
    multipleOf,
    required,
    validate,
    disabled,
    readOnly,
    placeholder,
    ...base
  } = options

  const digits = fractionDigits(currency, locale)
  const factor = 10 ** digits
  const symbol = useMemo(() => currencySymbol(currency, locale), [currency, locale])

  const fmt = useCallback(
    (minor: number) => formatMinor(minor, currency, { locale }),
    [currency, locale],
  )

  const ruleList = useMemo<ReadonlyArray<Rule<number>>>(
    () =>
      rules<number>(
        requiredRule<number>(required),
        minRule(min, fmt),
        maxRule(max, fmt),
        positiveRule(positive),
        negativeRule(negative),
        nonZeroRule(nonZero),
        wholeUnitsOnly && {
          rule: "integer",
          test: (v: number) => v % factor === 0,
        },
        multipleOfRule(multipleOf, fmt),
        custom<number>(validate),
      ),
    [required, min, max, positive, negative, nonZero, wholeUnitsOnly, multipleOf, validate, fmt, factor],
  )

  const field = useField<number>({
    component: "CurrencyInput",
    emptyValue: 0,
    rules: ruleList,
    ...base,
    required,
    disabled,
    readOnly,
    // Emit a plain integer to FormData, never a formatted string.
    serialize: (v) => String(v),
  })

  const { value, setValue } = field
  const ref = useRef<HTMLInputElement | null>(null)
  const display = value === 0 ? "" : fmt(value)

  /**
   * Digit accumulator. The input is read-only to the keyboard in the usual
   * sense: we intercept keys and rebuild the number, so the caret never has
   * anywhere to drift to.
   */
  const onKeyDown = useCallback(
    (e: KeyboardEvent<HTMLInputElement>) => {
      if (disabled || readOnly) return
      const k = e.key

      if (k >= "0" && k <= "9") {
        e.preventDefault()
        setValue(pushDigit(value, Number(k)))
        return
      }
      if (k === "Backspace") {
        e.preventDefault()
        setValue(popDigit(value))
        return
      }
      if (k === "Delete") {
        e.preventDefault()
        setValue(0)
        return
      }
      if (allowNegative && (k === "-" || k === "Minus")) {
        e.preventDefault()
        setValue(negate(value))
        return
      }
      if (k === "ArrowUp") {
        e.preventDefault()
        setValue(value + (stepProp ?? factor))
        return
      }
      if (k === "ArrowDown") {
        e.preventDefault()
        const next = value - (stepProp ?? factor)
        setValue(!allowNegative && next < 0 ? 0 : next)
        return
      }
      // Let shortcuts and navigation through; swallow everything else so
      // stray letters never appear in a money field.
      if (!ALLOWED_KEYS.has(k) && !e.metaKey && !e.ctrlKey) {
        e.preventDefault()
      }
    },
    [disabled, readOnly, value, setValue, allowNegative, stepProp, factor],
  )

  const step = useCallback(
    (direction: 1 | -1) => {
      if (disabled || readOnly) return
      const next = value + direction * (stepProp ?? factor)
      setValue(!allowNegative && next < 0 ? 0 : next)
    },
    [disabled, readOnly, value, setValue, stepProp, factor, allowNegative],
  )

  /* ---------------- smart paste ---------------- */

  const [sideEffect, setSideEffect] =
    useState<UseCurrencyInputResult["sideEffect"]>(null)
  const undoRef = useRef<number | null>(null)

  const onPaste = useCallback(
    (e: ClipboardEvent<HTMLInputElement>) => {
      if (disabled || readOnly) return
      const text = clipboardText(e)
      if (!text) return
      e.preventDefault()

      const result = parsePastedMoney(text, currency, locale)
      if (result.minor === null) return

      undoRef.current = value
      setValue(result.minor)
      setSideEffect(
        result.switchedTo
          ? {
              from: currency,
              to: result.switchedTo,
              label: `Detected ${result.switchedTo}`,
            }
          : null,
      )
    },
    [disabled, readOnly, currency, locale, value, setValue],
  )

  const dismissSideEffect = useCallback(() => setSideEffect(null), [])

  const undoPaste = useCallback(() => {
    if (undoRef.current === null) return
    setValue(undoRef.current)
    undoRef.current = null
    setSideEffect(null)
  }, [setValue])

  const inputProps = useMemo(
    () => ({
      ref,
      value: display,
      // Controlled with an intercepted keydown: onChange exists only to keep
      // React from warning about a controlled input with no handler.
      onChange: () => {},
      onKeyDown,
      onPaste,
      inputMode: "decimal" as const,
      autoComplete: "off" as const,
      disabled,
      readOnly,
      placeholder: placeholder ?? fmt(0),
    }),
    [display, onKeyDown, onPaste, disabled, readOnly, placeholder, fmt],
  )

  return {
    ...field,
    currency,
    locale,
    symbol,
    display,
    fractionDigits: digits,
    step,
    inputProps,
    sideEffect,
    dismissSideEffect,
    undoPaste,
  }
}

/**
 * Money maths and formatting. Framework-free.
 *
 * The canonical value is an INTEGER COUNT OF MINOR UNITS — 123450 is $1,234.50.
 * No float ever touches a price. This is the single most important decision in
 * the component: `0.1 + 0.2 !== 0.3` has cost real companies real money, and a
 * currency input that emits a float invites exactly that bug downstream.
 *
 * Zero-decimal currencies (JPY, KRW) fall out for free because the minor-unit
 * factor comes from Intl rather than a hardcoded 100.
 */

import { detectCurrency, parseLooseNumber, scrub } from "@inputcn/core/paste"

/** Cached formatters — constructing Intl.NumberFormat is expensive. */
const formatterCache = new Map<string, Intl.NumberFormat>()
const fractionCache = new Map<string, number>()

function key(locale: string, currency: string, opts = ""): string {
  return `${locale}|${currency}|${opts}`
}

/** Decimal places this currency uses. JPY → 0, USD → 2, KWD → 3. */
export function fractionDigits(currency: string, locale = "en-US"): number {
  const k = key(locale, currency)
  const hit = fractionCache.get(k)
  if (hit !== undefined) return hit

  let digits = 2
  try {
    digits =
      new Intl.NumberFormat(locale, { style: "currency", currency })
        .resolvedOptions().maximumFractionDigits ?? 2
  } catch {
    // Unknown currency code — fall back to the 2-decimal majority.
  }
  fractionCache.set(k, digits)
  return digits
}

/** 10 ** fractionDigits. 100 for USD, 1 for JPY. */
export function minorUnitFactor(currency: string, locale = "en-US"): number {
  return 10 ** fractionDigits(currency, locale)
}

export interface FormatOptions {
  locale?: string
  /** Render the currency symbol. Off by default — the UI shows it as an affix. */
  withSymbol?: boolean
  /** Force a sign for positive values. */
  signDisplay?: Intl.NumberFormatOptions["signDisplay"]
}

/** Minor units → the string the user sees. */
export function formatMinor(
  minor: number,
  currency: string,
  { locale = "en-US", withSymbol = false, signDisplay }: FormatOptions = {},
): string {
  const digits = fractionDigits(currency, locale)
  const k = key(locale, currency, `${withSymbol}|${signDisplay ?? ""}`)

  let fmt = formatterCache.get(k)
  if (!fmt) {
    fmt = new Intl.NumberFormat(locale, {
      ...(withSymbol ? { style: "currency", currency } : {}),
      minimumFractionDigits: digits,
      maximumFractionDigits: digits,
      ...(signDisplay ? { signDisplay } : {}),
    })
    formatterCache.set(k, fmt)
  }
  return fmt.format(minor / 10 ** digits)
}

/** The currency symbol for a locale, e.g. "$", "£", "R$". */
export function currencySymbol(currency: string, locale = "en-US"): string {
  try {
    const parts = new Intl.NumberFormat(locale, {
      style: "currency",
      currency,
    }).formatToParts(0)
    return parts.find((p) => p.type === "currency")?.value ?? currency
  } catch {
    return currency
  }
}

/**
 * Append a typed digit, register-style: the value fills from the right.
 *
 * This is why CurrencyInput cannot drift its caret — the caret never moves,
 * because the user is not editing a string, they are pushing digits onto a
 * number. Typing 1, 2, 3 gives 0.01 → 0.12 → 1.23.
 */
export function pushDigit(minor: number, digit: number, max = 1e12): number {
  const sign = minor < 0 ? -1 : 1
  const next = Math.abs(minor) * 10 + digit
  return next > max ? minor : sign * next
}

/** Remove the right-most digit. */
export function popDigit(minor: number): number {
  const sign = minor < 0 ? -1 : 1
  return sign * Math.floor(Math.abs(minor) / 10)
}

/** Flip the sign. */
export function negate(minor: number): number {
  return minor === 0 ? 0 : -minor
}

/** Whole currency units → minor units, rounded correctly. */
export function toMinor(major: number, currency: string, locale = "en-US"): number {
  return Math.round(major * minorUnitFactor(currency, locale))
}

/** Minor units → whole currency units. Lossy by nature — display only. */
export function toMajor(minor: number, currency: string, locale = "en-US"): number {
  return minor / minorUnitFactor(currency, locale)
}

export interface PastedMoney {
  minor: number | null
  /** Set when the pasted text named a different currency. */
  switchedTo?: string
}

/**
 * Smart paste. PRD §11.2.
 *
 * "$1,234.50 USD" → 123450 and a currency switch.
 * "1.234,50"      → 123450, detecting the German convention by structure
 *                   rather than assuming the caller's locale.
 */
export function parsePastedMoney(
  input: string,
  currency: string,
  locale = "en-US",
): PastedMoney {
  const text = scrub(input)
  if (!text) return { minor: null }

  const detected = detectCurrency(text)
  const target = detected ?? currency

  const major = parseLooseNumber(text)
  if (major === null) return { minor: null }

  return {
    minor: toMinor(major, target, locale),
    ...(detected && detected !== currency ? { switchedTo: detected } : {}),
  }
}
